jsonTools.init:
function init(bundle) {
  if (window._eliAdminTelemetryInspectorBooted) return;
  window._eliAdminTelemetryInspectorBooted = true;
  if (!eli || !eli.storage || !eli.ui || !eli.register) return;

  var STORE_CONFIG = "config";
  var ROW_PREFIX = "_telemetry_";

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  // 2026-05-19 v2: pretty tool names. Maps raw stat-key / tool-id
  // forms (snake_case, appOpenedX, single words) to the friendly
  // names users actually recognise. Falls back to title-case for
  // anything not in the table.
  var _TOOL_NAME_MAP = {
    risk: "Legal Risks",
    legal_risks: "Legal Risks",
    draft: "Build Draft",
    build_draft: "Build Draft",
    legal_review: "Legal Review",
    review_redlines: "Review Redlines",
    error: "Error Review",        // raw stat key: appOpenedError
    error_review: "Error Review",
    compare: "Compare",
    docuscrub: "Docuscrub",
    final_review: "Final Review",
    email_helper: "Email Helper",
    auto_emailer: "Email Generator",
    redline_email_pack: "Redline Email Pack",
    redline_authors: "Redline Authors",
    ask_eli: "Ask ELI",
    eli5: "ELI5 Explainer",
    eli5_explanations: "ELI5 Explanations",
    trophy_gallery: "Trophy Gallery",
    playbook_manager: "Playbook Manager",
    risk_rules_manager: "Risk Rules Manager",
    tool_manager: "Tool Manager",
    version_history: "Version History",
    refresh_eli: "Refresh ELI",
    eli_settings: "Settings",
    eli_telemetry: "Telemetry",
    eli_stats: "Stats Engine",
    eli_agent: "ELI Agent",
    bd_template_tester: "Template Tester",
    admin_library_publisher: "Library Publisher",
    admin_data_editor: "Data Editor",
    admin_template_studio: "Template Studio",
    admin_storage_inspector: "Storage Inspector",
    admin_team_guidance: "Team Guidance",
    admin_telemetry_inspector: "User Stats",
    admin_usage_viewer: "Usage Dashboard",
    tool_author_studio: "Tool Author Studio",
    usage_risks: "Usage Risks",
    focus_flow: "Focus Flow",
  };
  function _displayToolName(raw) {
    if (!raw) return "—";
    var s = String(raw).replace(/^appOpened/, "");
    var snake = s.replace(/([A-Z])/g, "_$1").replace(/^_/, "").toLowerCase();
    if (_TOOL_NAME_MAP[snake]) return _TOOL_NAME_MAP[snake];
    // Fallback: title-case the underscore-split.
    return snake.split("_").map(function (p) {
      return p ? p.charAt(0).toUpperCase() + p.slice(1) : "";
    }).join(" ").trim() || "—";
  }
  function _fmtTimeHM(ms) {
    if (!ms) return "—";
    try {
      var d = new Date(ms);
      var h = d.getHours();
      var m = d.getMinutes();
      var ap = h >= 12 ? "pm" : "am";
      var h12 = h % 12; if (h12 === 0) h12 = 12;
      return h12 + ":" + (m < 10 ? "0" + m : m) + ap;
    } catch (e) { return String(ms); }
  }
  function _fmtDateLong(iso) {
    if (!iso) return "—";
    var parts = String(iso).split("-");
    if (parts.length !== 3) return iso;
    var monthNames = ["January","February","March","April","May","June","July","August","September","October","November","December"];
    var weekdayNames = ["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];
    try {
      var d = new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]));
      return {
        weekday: weekdayNames[d.getDay()],
        month: monthNames[d.getMonth()],
        day: d.getDate(),
        year: d.getFullYear(),
      };
    } catch (e) { return iso; }
  }
  function _isToday(iso) {
    var today = new Date().toISOString().slice(0, 10);
    return iso === today;
  }
  function _fmtCost(usd) {
    var n = Number(usd || 0);
    if (!n) return "$0";
    if (n < 0.01) return "$" + n.toFixed(4);
    return "$" + n.toFixed(2);
  }
  function _fmtTokens(n) {
    n = Number(n) || 0;
    if (n < 1000) return String(n);
    if (n < 1000000) return (n / 1000).toFixed(1).replace(/\.0$/, "") + "k";
    return (n / 1000000).toFixed(1).replace(/\.0$/, "") + "M";
  }
  // Inline price table — matches eli_telemetry/engine.js etPriceTable.
  // Replicated so the inspector doesn't need a cross-tool dependency.
  function _estCost(tokensMap) {
    var prices = {
      "gemini-3.1-flash-lite-preview": { in: 0.04, out: 0.20 },
      "gemini-3.1-flash":              { in: 0.075, out: 0.30 },
      "gemini-2.5-flash":              { in: 0.075, out: 0.30 },
      "gemini-2.5-flash-lite-preview": { in: 0.04, out: 0.20 },
      "gemini-2.5-pro":                { in: 1.25, out: 5.00 },
      "gemini-1.5-pro":                { in: 1.25, out: 5.00 },
      "gemini-1.5-flash":              { in: 0.075, out: 0.30 },
      "_default":                      { in: 0.075, out: 0.30 },
    };
    if (!tokensMap || typeof tokensMap !== "object") return 0;
    var total = 0;
    Object.keys(tokensMap).forEach(function (model) {
      var t = tokensMap[model] || {};
      var price = prices[model] || prices._default;
      var inTok = Number(t.promptTokens) || 0;
      var outTok = Number(t.candidatesTokens) || 0;
      total += (inTok * price.in + outTok * price.out) / 1000000;
    });
    return total;
  }

  function _readLocalRows() {
    return eli.storage.getAll(STORE_CONFIG).then(function (rows) {
      return (rows || []).filter(function (r) {
        return r && typeof r.key === "string" && r.key.indexOf(ROW_PREFIX) === 0;
      }).sort(function (a, b) {
        return String(b.date || "").localeCompare(String(a.date || ""));
      });
    }).catch(function () { return []; });
  }

  function _renderEmpty(mount) {
    mount.innerHTML =
      '<div style="font-family:Inter,system-ui,sans-serif;padding:48px 24px;background:#f8fafc;min-height:100vh;">' +
        '<div style="max-width:720px;margin:0 auto;text-align:center;background:#fff;border:1px solid #e2e8f0;padding:56px 32px;">' +
          '<div style="font-size:42px;margin-bottom:16px;">📊</div>' +
          '<div style="font-family:Georgia,serif;font-size:24px;font-weight:800;color:#0f172a;margin-bottom:8px;letter-spacing:-0.01em;">No activity yet</div>' +
          '<div style="font-size:13px;color:#64748b;line-height:1.55;max-width:420px;margin:0 auto;">Launch any tool and your stats will start populating here — by day, by tool, with AI cost and model usage.</div>' +
        '</div>' +
      '</div>';
  }

  function _render(mount, rows) {
    if (!rows || !rows.length) { _renderEmpty(mount); return; }
    var userKey = rows[0].userKey || "?";
    var userName = rows[0].userName || "?";
    // Doc-wide totals across all days for the inspector header.
    var totalToolsUsed = {};
    var totalCost = 0;
    var totalCalls = 0;
    rows.forEach(function (r) {
      var tu = r.toolsUsed || {};
      Object.keys(tu).forEach(function (k) {
        totalToolsUsed[k] = (totalToolsUsed[k] || 0) + (Number(tu[k]) || 0);
      });
      totalCost += _estCost(r.tokens || {});
      Object.values(r.tokens || {}).forEach(function (m) {
        totalCalls += Number((m && m.calls) || 0);
      });
    });
    var totalLaunchesAllDays = Object.keys(totalToolsUsed).reduce(function (n, k) {
      return n + totalToolsUsed[k];
    }, 0);
    // 2026-05-19 v3: more color, premium cost styling, token direction
    // labels (↑ sent / ↓ received), avg-cost-per-use per tool, and
    // collapsed aggregate sections at the bottom (All-Time by Tool /
    // by Model + Highlights). Day cards stay the primary structure.
    var activeDays = rows.length;
    // Premium cost renderer — Georgia serif, gold, tabular-nums.
    // `size` keys: hero (28), day (22), row (14), small (11).
    function _premiumCost(usd, size) {
      var n = Number(usd || 0);
      var text;
      if (!n) text = "$0";
      else if (n < 0.01) text = "$" + n.toFixed(4);
      else text = "$" + n.toFixed(2);
      var sizes = {
        hero:  "font-size:28px;letter-spacing:-0.01em;font-weight:800;",
        day:   "font-size:22px;letter-spacing:-0.01em;font-weight:800;",
        row:   "font-size:14px;font-weight:700;",
        small: "font-size:11px;font-weight:700;",
      };
      var s = sizes[size] || sizes.row;
      return '<span style="font-family:Georgia,\'Times New Roman\',serif;color:#b8961f;font-variant-numeric:tabular-nums;line-height:1;' + s + '">' + text + '</span>';
    }
    // Tokens with directional label + color: ↑ sent (blue), ↓ received (teal).
    function _tokenIO(inTok, outTok) {
      return '<span style="color:#1565c0;font-weight:700;" title="Tokens sent to the AI (prompt)">↑ ' + _fmtTokens(inTok) + '</span>' +
             '<span style="color:#94a3b8;margin:0 6px;">·</span>' +
             '<span style="color:#0d9488;font-weight:700;" title="Tokens received from the AI (response)">↓ ' + _fmtTokens(outTok) + '</span>';
    }
    // ─── AGGREGATE COMPUTATION ─────────────────────────────────────────
    // Per-tool all-time: count, cost, days-used, avg-cost-per-use.
    var aggByTool = {};
    var aggByModel = {};
    var maxDayLaunches = 0;
    var bestDay = null;     // { date, launches, cost, calls }
    var totalIn = 0, totalOut = 0;
    rows.forEach(function (r) {
      var tbt = r.tokensByTool || {};
      // Tools — union of toolsUsed keys + tokensByTool keys.
      var union = {};
      Object.keys(r.toolsUsed || {}).forEach(function (k) { union[k] = true; });
      Object.keys(tbt).forEach(function (k) { if (k !== "_unknown") union[k] = true; });
      Object.keys(union).forEach(function (t) {
        if (!aggByTool[t]) aggByTool[t] = { count: 0, cost: 0, days: 0 };
        var c = Number((r.toolsUsed || {})[t]) || 0;
        var k = _estCost(tbt[t] || {});
        aggByTool[t].count += c;
        aggByTool[t].cost += k;
        if (c > 0 || k > 0) aggByTool[t].days += 1;
      });
      // Models — union across all days.
      Object.keys(r.tokens || {}).forEach(function (model) {
        var m = r.tokens[model] || {};
        if (!aggByModel[model]) aggByModel[model] = { calls: 0, promptTokens: 0, candidatesTokens: 0, cost: 0 };
        aggByModel[model].calls += Number(m.calls) || 0;
        aggByModel[model].promptTokens += Number(m.promptTokens) || 0;
        aggByModel[model].candidatesTokens += Number(m.candidatesTokens) || 0;
        aggByModel[model].cost += _estCost({ [model]: m });
        totalIn += Number(m.promptTokens) || 0;
        totalOut += Number(m.candidatesTokens) || 0;
      });
      // Best day (by launches, tiebreak by cost).
      var dl = 0;
      Object.values(r.toolsUsed || {}).forEach(function (n) { dl += Number(n) || 0; });
      var dc = _estCost(r.tokens || {});
      var dcalls = 0;
      Object.values(r.tokens || {}).forEach(function (m) { dcalls += Number((m && m.calls) || 0); });
      if (dl > maxDayLaunches || (dl === maxDayLaunches && dc > ((bestDay && bestDay.cost) || 0))) {
        maxDayLaunches = dl;
        bestDay = { date: r.date, launches: dl, cost: dc, calls: dcalls };
      }
    });
    // Distinct tools used across history.
    var distinctTools = Object.keys(aggByTool).filter(function (t) {
      return aggByTool[t].count > 0;
    }).length;
    // Active streak — consecutive days from most recent date backwards.
    var streak = 0;
    var todayIso = new Date().toISOString().slice(0, 10);
    (function () {
      var dateSet = {};
      rows.forEach(function (r) { dateSet[r.date] = true; });
      var d = new Date();
      if (!dateSet[todayIso]) d.setDate(d.getDate() - 1);
      while (true) {
        var iso = d.toISOString().slice(0, 10);
        if (!dateSet[iso]) break;
        streak += 1;
        d.setDate(d.getDate() - 1);
      }
    })();
    var html = '';
    html += '<div style="font-family:Inter,system-ui,sans-serif;background:#f8fafc;min-height:100vh;padding:32px 24px 60px 24px;">';
    html += '<div style="max-width:780px;margin:0 auto;">';
    // ─── HERO / COVER ──────────────────────────────────────────────────
    html += '<div style="background:linear-gradient(180deg,#fff 0%,#fafbfc 100%);border:1px solid #e2e8f0;padding:32px 36px 28px 36px;margin-bottom:18px;box-shadow:0 1px 0 rgba(15,23,42,0.04);">';
    html +=   '<div style="display:flex;align-items:center;gap:8px;">';
    html +=     '<span style="font-size:11px;line-height:1;color:#c9a227;">◆</span>';
    html +=     '<span style="font-size:10px;font-weight:800;color:#94a3b8;text-transform:uppercase;letter-spacing:0.22em;">User Stats</span>';
    html +=   '</div>';
    html +=   '<div style="font-family:Georgia,\'Times New Roman\',serif;font-size:32px;font-weight:800;color:#0f172a;margin-top:6px;letter-spacing:-0.01em;line-height:1.1;">' + _esc(userName) + '</div>';
    html +=   '<div style="display:flex;gap:0;margin-top:24px;border-top:1px solid #e2e8f0;padding-top:18px;flex-wrap:wrap;">';
    function _heroStat(num, lbl, color, isFirst, isLast) {
      var border = isLast ? "" : "border-right:1px solid #e2e8f0;";
      var padL = isFirst ? "0" : "16px";
      var padR = isLast ? "0" : "16px";
      return '<div style="flex:1;min-width:120px;padding:0 ' + padR + ' 0 ' + padL + ';' + border + '">' +
        '<div style="font-family:Georgia,\'Times New Roman\',serif;font-size:30px;font-weight:800;color:' + color + ';line-height:1;letter-spacing:-0.01em;font-variant-numeric:tabular-nums;">' + num + '</div>' +
        '<div style="font-size:9.5px;font-weight:800;color:#64748b;text-transform:uppercase;letter-spacing:0.16em;margin-top:10px;">' + lbl + '</div>' +
      '</div>';
    }
    html +=     _heroStat(activeDays, "Active Days", "#0f172a", true, false);
    html +=     _heroStat(totalLaunchesAllDays, "Tool Launches", "#1e3a8a", false, false);
    html +=     _heroStat(totalCalls, "AI Calls", "#0d9488", false, false);
    html +=     '<div style="flex:1;min-width:120px;padding:0 0 0 16px;">' +
                  _premiumCost(totalCost, "hero") +
                  '<div style="font-size:9.5px;font-weight:800;color:#64748b;text-transform:uppercase;letter-spacing:0.16em;margin-top:10px;">Total Spend</div>' +
                '</div>';
    html +=   '</div>';
    html += '</div>';
    // ─── HIGHLIGHTS STRIP — color-block callouts ───────────────────────
    html += '<div style="display:flex;gap:10px;margin-bottom:24px;flex-wrap:wrap;">';
    function _highlightCard(icon, value, label, accent, bg) {
      return '<div style="flex:1;min-width:170px;background:' + bg + ';border:1px solid ' + accent + '40;border-left:3px solid ' + accent + ';padding:14px 16px;display:flex;align-items:center;gap:12px;">' +
        '<div style="font-size:22px;line-height:1;">' + icon + '</div>' +
        '<div style="min-width:0;flex:1;">' +
          '<div style="font-family:Georgia,\'Times New Roman\',serif;font-size:18px;font-weight:800;color:' + accent + ';line-height:1;letter-spacing:-0.01em;font-variant-numeric:tabular-nums;">' + value + '</div>' +
          '<div style="font-size:9px;font-weight:800;color:#64748b;text-transform:uppercase;letter-spacing:0.16em;margin-top:6px;">' + label + '</div>' +
        '</div>' +
      '</div>';
    }
    html +=   _highlightCard("🔥", (streak || 0) + (streak === 1 ? " day" : " days"), "Active Streak", "#dc2626", "linear-gradient(180deg,#fff7ed,#ffedd5)");
    if (bestDay) {
      var bestDate = _fmtDateLong(bestDay.date);
      html += _highlightCard("🏆", bestDay.launches + " launches", "Best Day · " + (bestDate.month || "").slice(0, 3) + " " + (bestDate.day || ""), "#15803d", "linear-gradient(180deg,#f0fdf4,#dcfce7)");
    }
    html +=   _highlightCard("🧰", distinctTools + " tools", "Distinct Tools Used", "#1e3a8a", "linear-gradient(180deg,#eff6ff,#dbeafe)");
    html += '</div>';
    // ─── PER-DAY LEDGER ────────────────────────────────────────────────
    rows.forEach(function (r) {
      var dayDate = _fmtDateLong(r.date);
      var isToday = _isToday(r.date);
      var tbt = r.tokensByTool || {};
      var unionToolNames = {};
      Object.keys(r.toolsUsed || {}).forEach(function (k) { unionToolNames[k] = true; });
      Object.keys(tbt).forEach(function (k) { if (k !== "_unknown") unionToolNames[k] = true; });
      var toolEntries = Object.keys(unionToolNames).map(function (t) {
        var c = Number((r.toolsUsed || {})[t]) || 0;
        var k = _estCost(tbt[t] || {});
        return {
          tool: t,
          count: c,
          cost: k,
          avg: c > 0 ? (k / c) : 0,
        };
      }).sort(function (a, b) {
        if (b.count !== a.count) return b.count - a.count;
        return b.cost - a.cost;
      });
      var dayLaunches = toolEntries.reduce(function (n, e) { return n + e.count; }, 0);
      var dayCost = _estCost(r.tokens || {});
      var dayCalls = Object.values(r.tokens || {}).reduce(function (n, m) {
        return n + Number((m && m.calls) || 0);
      }, 0);
      var maxToolCount = toolEntries.length ? toolEntries[0].count : 1;
      var unkCost = _estCost(tbt._unknown || {});
      // Day card — gold left rail when today.
      html += '<div style="background:#fff;border:1px solid #e2e8f0;margin-bottom:20px;box-shadow:0 1px 0 rgba(15,23,42,0.04);' +
              (isToday ? 'border-left:4px solid #c9a227;' : '') + '">';
      // Day header — weekday + month on left, big day number on right.
      html +=   '<div style="display:flex;justify-content:space-between;align-items:flex-start;padding:22px 28px 18px 28px;border-bottom:1px solid #f1f5f9;gap:16px;background:' + (isToday ? 'linear-gradient(180deg,#fffbeb 0%,#fff 100%)' : '#fff') + ';">';
      html +=     '<div style="min-width:0;flex:1;">';
      html +=       '<div style="display:flex;align-items:center;gap:8px;">';
      html +=         '<span style="font-size:10px;font-weight:800;color:' + (isToday ? '#b8961f' : '#64748b') + ';text-transform:uppercase;letter-spacing:0.22em;">' + _esc(dayDate.weekday || "") + '</span>';
      if (isToday) html += '<span style="font-size:9px;font-weight:900;color:#fff;background:#c9a227;padding:2px 7px;letter-spacing:0.1em;text-transform:uppercase;border-radius:0;">Today</span>';
      html +=       '</div>';
      html +=       '<div style="font-size:10px;color:#94a3b8;letter-spacing:0.08em;margin-top:3px;">' + _esc((dayDate.month || "") + " " + (dayDate.year || "")) + '</div>';
      // Day-level stat strip — colored pills.
      html +=       '<div style="display:flex;gap:14px;margin-top:14px;font-variant-numeric:tabular-nums;flex-wrap:wrap;align-items:center;">';
      html +=         '<div style="display:inline-flex;align-items:baseline;gap:5px;"><span style="font-size:20px;font-weight:800;color:#0f172a;">' + dayLaunches + '</span><span style="font-size:10.5px;color:#475569;font-weight:600;">launch' + (dayLaunches === 1 ? '' : 'es') + '</span></div>';
      if (dayCalls > 0) html += '<div style="display:inline-flex;align-items:baseline;gap:5px;padding-left:14px;border-left:1px solid #e2e8f0;"><span style="font-size:20px;font-weight:800;color:#0d9488;">' + dayCalls + '</span><span style="font-size:10.5px;color:#475569;font-weight:600;">AI call' + (dayCalls === 1 ? '' : 's') + '</span></div>';
      if (dayCost > 0) html += '<div style="display:inline-flex;align-items:baseline;gap:5px;padding-left:14px;border-left:1px solid #e2e8f0;">' + _premiumCost(dayCost, "day") + '<span style="font-size:10.5px;color:#475569;font-weight:600;">spent</span></div>';
      html +=       '</div>';
      if (r.firstActiveAt || r.lastActiveAt) {
        html +=     '<div style="font-size:10.5px;color:#94a3b8;margin-top:12px;letter-spacing:0.02em;">⏱ Active ' + _fmtTimeHM(r.firstActiveAt) + ' – ' + _fmtTimeHM(r.lastActiveAt) + '</div>';
      }
      html +=     '</div>';
      html +=     '<div style="text-align:right;flex-shrink:0;">';
      html +=       '<div style="font-family:Georgia,\'Times New Roman\',serif;font-size:52px;font-weight:800;color:' + (isToday ? '#c9a227' : '#0f172a') + ';line-height:1;letter-spacing:-0.025em;font-variant-numeric:tabular-nums;">' + _esc(dayDate.day || "") + '</div>';
      html +=     '</div>';
      html +=   '</div>';
      // ── TOOLS section ───────────────────────────────────────────────
      if (toolEntries.length === 0 && unkCost <= 0) {
        html += '<div style="padding:20px 28px;font-size:11.5px;color:#94a3b8;font-style:italic;">No activity recorded for this day.</div>';
      } else {
        html += '<div style="padding:16px 28px 8px 28px;">';
        html +=   '<div style="display:flex;align-items:center;gap:8px;margin-bottom:12px;">';
        html +=     '<span style="font-size:11px;color:#c9a227;line-height:1;">◆</span>';
        html +=     '<span style="font-size:10px;font-weight:800;color:#475569;text-transform:uppercase;letter-spacing:0.2em;">Tools</span>';
        html +=     '<span style="flex:1;height:1px;background:linear-gradient(90deg,#e2e8f0,transparent);"></span>';
        html +=   '</div>';
        toolEntries.forEach(function (e, idx) {
          var pct = e.count > 0 ? Math.max(4, Math.round((e.count / maxToolCount) * 100)) : 0;
          var rowBg = idx % 2 === 0 ? "#fff" : "#fcfcfd";
          html += '<div style="display:flex;align-items:center;gap:12px;padding:10px 12px;background:' + rowBg + ';border:1px solid #f1f5f9;border-radius:0;margin-bottom:5px;font-variant-numeric:tabular-nums;">';
          // Tool name + bar stacked
          html +=   '<div style="flex:1;min-width:0;">';
          html +=     '<div style="font-size:13px;color:#0f172a;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-bottom:4px;">' + _esc(_displayToolName(e.tool)) + '</div>';
          html +=     '<div style="height:5px;background:#f1f5f9;position:relative;overflow:hidden;border-radius:0;">' +
                        '<div style="position:absolute;inset:0;width:' + pct + '%;background:linear-gradient(90deg,#1565c0,#0d47a1);"></div>' +
                      '</div>';
          html +=   '</div>';
          // Count
          html +=   '<div style="flex:0 0 60px;text-align:right;">';
          html +=     '<div style="font-size:16px;font-weight:800;color:#0f172a;line-height:1;">' + e.count + '</div>';
