        html += '<div style="padding:12px 14px;background:linear-gradient(180deg,#f0fdfa,#fff);border:1px solid #99f6e4;border-left:3px solid #0d9488;margin-bottom:7px;font-variant-numeric:tabular-nums;">';
        html +=   '<div style="display:flex;justify-content:space-between;align-items:baseline;gap:12px;margin-bottom:7px;">';
