    var resetCdnBtn = mount.querySelector("#atiResetCdn");
    if (resetCdnBtn) {
      resetCdnBtn.onclick = function () {
        function _lsGet(k) {
          try { return (eli.compat && eli.compat.lsGet) ? (eli.compat.lsGet(k) || "") : ""; }
          catch (_e) { return ""; }
        }
        var pat = _lsGet("eli_user_github_pat");
        var repo = _lsGet("eli_github_repo");
        var branch = _lsGet("eli_github_branch") || "main";
        if (!pat || !repo) {
          if (typeof showToast === "function") showToast("Missing GitHub PAT or repo — import credentials via main Settings → Import Credentials first.", "err");
          return;
        }
        var keyForCdn = String((rows[0] && rows[0].userKey) || "").toLowerCase().trim();
        if (!keyForCdn) {
          if (typeof showToast === "function") showToast("No userKey found — can't determine CDN file path.", "err");
          return;
        }
        var filePath = "usage/" + keyForCdn + ".json";
        eli.ui.confirm({
          title: "Reset cloud stats?",
          message:
            "Wipes your cloud copy so the next reload starts fresh.\n\n" +
            "Only affects your own stats — nobody else's.",
          confirmLabel: "Reset Cloud",
          danger: true,
        }).then(function (ok) {
          if (!ok) return;
          resetCdnBtn.disabled = true;
          resetCdnBtn.textContent = "⏳ Wiping…";
          function _strToB64(s) {
            var utf8 = unescape(encodeURIComponent(s));
            return btoa(utf8);
          }
          // GET current SHA so the PUT is a clean update (not a create).
          var getUrl = "https://api.github.com/repos/" + repo + "/contents/" +
            encodeURIComponent(filePath).replace(/%2F/g, "/") +
            "?ref=" + encodeURIComponent(branch) + "&t=" + Date.now();
          fetch(getUrl, {
            cache: "no-store",
            headers: {
              "Authorization": "Bearer " + pat,
              "Accept": "application/vnd.github+json",
              "X-GitHub-Api-Version": "2022-11-28",
            },
          }).then(function (r) {
            if (r.status === 404) return null;
            if (!r.ok) return r.text().then(function (t) { throw new Error("GET failed: HTTP " + r.status + " · " + t.slice(0, 200)); });
            return r.json();
          }).then(function (existing) {
            var cleared = {
              userName: (rows[0] && rows[0].userName) || keyForCdn.toUpperCase(),
              userKey: keyForCdn,
              generatedAt: new Date().toISOString(),
              days: [],
              note: "Cleared " + new Date().toISOString().slice(0, 10) +
                " via Telemetry Inspector — neutralizes MAX-merge bringing back stale counts.",
            };
            var putUrl = "https://api.github.com/repos/" + repo + "/contents/" +
              encodeURIComponent(filePath).replace(/%2F/g, "/");
            var body = {
              message: "Telemetry Inspector: clear " + filePath,
              content: _strToB64(JSON.stringify(cleared, null, 2) + "\n"),
              branch: branch,
            };
            if (existing && existing.sha) body.sha = existing.sha;
            return fetch(putUrl, {
              method: "PUT",
              headers: {
                "Authorization": "Bearer " + pat,
                "Accept": "application/vnd.github+json",
                "X-GitHub-Api-Version": "2022-11-28",
                "Content-Type": "application/json",
              },
              body: JSON.stringify(body),
            }).then(function (r) {
              if (!r.ok) return r.text().then(function (t) { throw new Error("PUT failed: HTTP " + r.status + " · " + t.slice(0, 200)); });
              return r.json();
            });
          }).then(function () {
            // Purge jsdelivr cache so the next telemetry boot sees the
            // cleared file immediately (not the cached old version).
            var purgeUrl = "https://purge.jsdelivr.net/gh/" + repo + "@" + branch + "/" + filePath;
            return fetch(purgeUrl).catch(function () { /* tolerate purge failures */ });
          }).then(function () {
            if (typeof showToast === "function") showToast("Cloud stats reset. Reload to start fresh.", "ok");
            resetCdnBtn.disabled = false;
            resetCdnBtn.textContent = "Reset CDN";
          }).catch(function (err) {
            if (typeof showToast === "function") showToast("Cloud reset failed: " + ((err && err.message) || err), "err");
            resetCdnBtn.disabled = false;
            resetCdnBtn.textContent = "Reset CDN";
          });
        });
      };
    }
  }

  function _open() {
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedAdminTelemetryInspector"); } catch (e) {}
    var out = eli.ui && typeof eli.ui.claimOutput === "function" ? eli.ui.claimOutput() : document.getElementById("output");
    if (!out) {
      if (typeof showToast === "function") showToast("Dashboard root missing", "err");
      return;
    }
    // Force block layout so the kernel's flex doesn't squish our content.
    var wrap = document.createElement("div");
    wrap.style.cssText = "display:block;width:100%;box-sizing:border-box;";
    out.appendChild(wrap);
    wrap.innerHTML = '<div style="padding:40px;text-align:center;color:#64748b;font-family:Inter,system-ui,sans-serif;">Reading IDB…</div>';
    _readLocalRows().then(function (rows) { _render(wrap, rows); });
  }

  eli.register({
    tile: { app_admin_telemetry_inspector: _open },
    admin_telemetry_inspector: { open: _open },
  });

  eli.log.event("tool", "admin_telemetry_inspector_initialized", {});
